import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  const ownedGeometries = [];
  const ownedMaterials = [];
  const loadedTextures = [];
  let disposed = false;

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = {
    ink: visualSpec.colors?.ink ?? '#16161d',
    paper: visualSpec.colors?.paper ?? '#e8ecf2',
    accent: visualSpec.colors?.accent ?? '#ff2a38',
    surface: visualSpec.colors?.surface ?? '#0b0b10'
  };

  const hexRgb = (value) => {
    const hex = String(value).replace('#', '');
    const normalized = hex.length === 3
      ? hex.split('').map((v) => v + v).join('')
      : hex;
    return [
      parseInt(normalized.slice(0, 2), 16) / 255,
      parseInt(normalized.slice(2, 4), 16) / 255,
      parseInt(normalized.slice(4, 6), 16) / 255
    ];
  };

  const addOwned = (geometry, material) => {
    ownedGeometries.push(geometry);
    ownedMaterials.push(material);
    return new THREE.Mesh(geometry, material);
  };

  const gradientStops = visualSpec.gradientStops;
  const topColor = hexRgb(
    Array.isArray(gradientStops) && gradientStops.length
      ? gradientStops[gradientStops.length - 1]?.color ?? colors.ink
      : colors.ink
  );
  const bottomColor = hexRgb(
    Array.isArray(gradientStops) && gradientStops.length
      ? gradientStops[0]?.color ?? colors.surface
      : colors.surface
  );

  const backdropGeometry = new THREE.PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial({
    transparent: false,
    depthWrite: true
  });
  backdropMaterial.colorNode = mix(
    vec3(...bottomColor),
    vec3(...topColor),
    smoothstep(0.04, 0.96, uv().y)
  );
  const backdrop = addOwned(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const groundGeometry = new THREE.CircleGeometry(1.35, 64);
  const groundMaterial = new MeshBasicNodeMaterial({
    color: new THREE.Color(colors.ink),
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  const ground = addOwned(groundGeometry, groundMaterial);
  ground.scale.set(1.7, 0.42, 1);
  ground.position.set(0, -0.58, -0.35);
  ground.rotation.x = -Math.PI / 2;
  root.add(ground);

  const subject = new THREE.Group();
  subject.position.z = 0.12;
  root.add(subject);

  const items = config.textContent ?? visualSpec.textContent ?? [];
  for (const item of items) {
    const text = ctx.fontAtlas.createText(String(item.text ?? ''), {
      fontSize: item.typography?.fontSize ?? 96,
      color: colors.paper,
      align: item.typography?.align ?? 'center',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx
    });
    text.position.set(0, 0.08, 0.18);
    subject.add(text);
  }

  const accentGeometry = new THREE.BoxGeometry(1.35, 0.035, 0.025);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: new THREE.Color(colors.accent)
  });
  const accent = addOwned(accentGeometry, accentMaterial);
  accent.position.set(-0.02, -0.48, 0.16);
  subject.add(accent);

  const sourceRect = visualSpec.atlasRegion?.sourceRect ?? {
    x: 0,
    y: 0,
    width: 512,
    height: 320
  };

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    const imageGeometry = new THREE.PlaneGeometry(1.6, 1);
    const imageMaterial = new MeshBasicNodeMaterial({
      transparent: true,
      depthWrite: false,
      opacity: 0.9
    });
    const imageMesh = addOwned(imageGeometry, imageMaterial);
    imageMesh.position.set(2.28, -0.38, 0.05);
    imageMesh.rotation.z = -0.16;
    subject.add(imageMesh);

    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose();
        return;
      }

      loadedTextures.push(texture);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.flipY = false;

      const width = texture.image?.width ?? sourceRect.width;
      const height = texture.image?.height ?? sourceRect.height;
      texture.repeat.set(
        sourceRect.width / width,
        sourceRect.height / height
      );
      texture.offset.set(
        sourceRect.x / width,
        1 - ((sourceRect.y + sourceRect.height) / height)
      );
      texture.needsUpdate = true;

      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  root.onBeforeRender = (_renderer, _scene, camera) => {
    if (!disposed && camera) root.quaternion.copy(camera.quaternion);
  };

  const entrance = gsap.timeline({ paused: false });
  entrance.fromTo(
    subject.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.42, ease: 'power3.out' }
  ).to(
    subject.scale,
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
  );

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    entrance.kill();
    root.onBeforeRender = null;

    for (const texture of loadedTextures) texture.dispose();
    for (const material of ownedMaterials) material.dispose();
    for (const geometry of ownedGeometries) geometry.dispose();

    root.clear();
  };

  return root;
}
